"""Original gastrointestinal neuroendocrine tumor questions."""
from qbank_authoring import question,ref,finalize
GI=ref('NCI PDQ: Gastrointestinal Neuroendocrine Tumors','https://www.cancer.gov/types/gi-neuroendocrine-tumors/hp/gi-neuroendocrine-treatment-pdq')
PN=ref('NCI PDQ: Pancreatic Neuroendocrine Tumors','https://www.cancer.gov/types/pancreatic/hp/pnet-treatment-pdq')
EN=ref('ENETS 2023 Gastroduodenal Neuroendocrine Tumor Guidance','https://doi.org/10.1111/jne.13306')
NA=ref('NANETS 2020 Pancreatic NET Surveillance and Medical Management Consensus','https://ww.nanets.net/images/guidelines/2020_NANETS_Guidelines_2020_Surveillance_and_Medical_Management_of_Pancreatic_Neuroendocrine_Tumors.pdf')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('A patient with an ileal neuroendocrine tumor and liver metastases develops flushing, watery diarrhea and bronchospasm. Which biochemical test most directly assesses serotonin overproduction?', 'Urinary 5-HIAA measured with appropriate collection and dietary/medication preparation',[
 ('Serum CA 19-9','This is not a serotonin metabolite and is not the relevant functional test.'),('Serum gastrin alone','Gastrin evaluates a different secretory syndrome and requires acid-context interpretation.'),('Fecal elastase alone','This assesses exocrine pancreatic function, not serotonin production.')],
 'Choose the marker for the functional syndrome', '**5-HIAA is a major metabolite of serotonin.**', ['Collection quality, diet, drugs and renal function can affect interpretation.','A functional marker complements rather than replaces imaging and histology.'], '**Assess complications of sustained hormone exposure.**', ['Carcinoid heart disease and nutritional effects may require evaluation.','A nonfunctioning NET may not produce an elevated functional marker.'], [['Flushing/secretory diarrhea','Consider serotonin syndrome'],['5-HIAA','Serotonin metabolite'],['Gastrin','Different hormone axis']], [GI], 'clinical_scenario')
q('Why does a small intestinal NET commonly produce systemic carcinoid syndrome only after liver metastases develop?', 'Hepatic metabolism normally limits systemic exposure to vasoactive products entering the portal circulation',[
 ('All small intestinal NETs are hormonally inactive before metastasis','They can secrete products before systemic manifestations emerge.'),('Liver metastases always transform the tumor into a different histology','The syndrome does not require histological transformation.'),('Serotonin is produced only by hepatocytes surrounding metastases','The tumor is the relevant source.')],
 'Anatomical drainage modifies the clinical phenotype', '**Portal delivery permits first-pass metabolism of secreted mediators.**', ['Hepatic metastases can release products directly into systemic venous outflow.','Tumors outside portal drainage can produce syndrome without liver metastases.'], '**Do not use absence of syndrome to exclude a NET.**', ['Many NETs are nonfunctioning or have insufficient systemic hormone exposure.','Functional activity and anatomical stage are related but distinct.'], [['Portal-confined secretion','Hepatic first-pass effect'],['Liver metastases','Systemic mediator exposure'],['Extra-portal primary','Possible exception']], [GI])
q('Which valvular pattern is most characteristic of carcinoid heart disease?', 'Tricuspid regurgitation with pulmonary valve stenosis or regurgitation from fibrotic right-sided valve disease',[
 ('Isolated rheumatic mitral stenosis with commissural fusion','That is not the typical carcinoid pattern.'),('Acute aortic regurgitation from infective endocarditis','This has a different mechanism and diagnostic context.'),('Dynamic left ventricular outflow obstruction','This is not the characteristic serotonin-associated valvulopathy.')],
 'The right heart receives the highest mediator exposure', '**Fibrotic plaques can retract and immobilize right-sided valve leaflets.**', ['Pulmonary metabolism usually reduces left-sided exposure.','Left-sided disease can occur with special circumstances such as a right-to-left shunt or bronchial primary.'], '**Evaluate with echocardiography in the appropriate syndrome.**', ['Assess right ventricular consequences as well as valve morphology.','Cardiac disease can affect procedural and oncology planning.'], [['Tricuspid valve','Often regurgitant'],['Pulmonary valve','Stenotic and/or regurgitant'],['Left-sided involvement','Consider an exception to usual exposure']], [GI])
q('What is an appropriate first-line hormone-control strategy for a patient with symptomatic carcinoid syndrome from an unresectable well-differentiated NET?', 'A somatostatin analogue such as octreotide or lanreotide',[
 ('High-dose PPI as the primary serotonin-suppression treatment','PPIs control acid and do not directly address this serotonin-mediated syndrome.'),('Diazoxide as the standard flushing treatment','Diazoxide is used for insulin-mediated hypoglycemia, not routine carcinoid syndrome.'),('Pancreatic enzyme replacement as the sole hormone-suppressive therapy','PERT treats maldigestion rather than tumor mediator secretion.')],
 'Control secretion while planning tumor-directed treatment', '**Somatostatin analogues can reduce functional symptoms and can also have an antiproliferative role in selected NETs.**', ['Dose and formulation depend on symptoms and disease context.','Persistent diarrhea may also reflect bile acid loss, exocrine insufficiency or another cause.'], '**Reassess apparent treatment failure before escalation.**', ['Check administration, tumor progression and competing mechanisms.','Hormone control does not imply eradication of the tumor.'], [['Octreotide/lanreotide','Hormonal symptom control'],['Tumor-directed therapy','Selected by stage and biology'],['Persistent diarrhea','Assess multiple mechanisms']], [GI], 'clinical_scenario')
q('Which factor is especially important when considering peptide receptor radionuclide therapy with lutetium-177 DOTATATE?', 'Demonstrable somatostatin receptor expression on appropriate functional imaging',[
 ('A CA 19-9 elevation alone','This does not establish the receptor target.'),('Poor differentiation as the sole positive selection criterion','Poorly differentiated carcinoma has different biology and often a different treatment pathway.'),('Absence of all receptor uptake as evidence of maximal targeting','The therapy depends on receptor-mediated delivery.')],
 'Target expression makes receptor-directed treatment plausible', '**PRRT delivers radiation through a somatostatin receptor ligand.**', ['Disease distribution, progression, grade and prior treatment affect selection.','Renal and marrow reserve must be assessed.'], '**Integrate receptor imaging with anatomical imaging and pathology.**', ['Not all NET lesions have identical biology or uptake.','A receptor-negative aggressive component may require a different strategy.'], [['Receptor-positive disease','Potential target'],['Renal/marrow reserve','Treatment safety assessment'],['Discordant lesions','Reassess biology']], [GI,NA])
q('A well-differentiated gastroenteropancreatic NET has a Ki-67 index of 12%. What grade is it?', 'Grade 2',[
 ('Grade 1','The G1 Ki-67 threshold is below 3%.'),('Grade 3 solely because any value above 10% is G3','The Ki-67 threshold for G3 is above 20%.'),('Poorly differentiated neuroendocrine carcinoma by definition','Grade and differentiation are separate; a G2 well-differentiated tumor is not NEC.')],
 'Proliferation grade and differentiation describe different properties', '**A Ki-67 index from 3% through 20% corresponds to G2 in digestive well-differentiated NETs.**', ['Mitotic rate also contributes; discordant measures require pathological interpretation.','Sampling can miss a higher-proliferation region.'], '**Use grade alongside morphology and stage.**', ['A well-differentiated G3 NET is distinct from poorly differentiated NEC.','The distinction changes treatment choices and prognosis.'], [['G1 Ki-67','<3%'],['G2 Ki-67','3–20%'],['G3 Ki-67','>20%']], [EN])
q('Multiple small gastric body NETs occur with autoimmune corpus atrophy, low gastric acidity and hypergastrinemia. Which type is most likely?', 'Type 1 gastric NET',[
 ('Type 2 gastric NET','This is associated with gastrinoma/Zollinger–Ellison syndrome, often in MEN1, with an acid-hypersecretory context.'),('Type 3 gastric NET','Sporadic type 3 disease typically lacks the hypergastrinemic atrophic-gastritis background.'),('Gastric adenocarcinoma solely because gastrin is elevated','The stated neuroendocrine histology and background support a different classification.')],
 'Interpret gastrin together with gastric acidity and background mucosa', '**Loss of acid feedback in corpus atrophy drives gastrin-mediated ECL-cell proliferation.**', ['These lesions are often multiple and small.','Size, grade, depth and other risk findings guide local management.'], '**Assess the background disease as well as the tumors.**', ['B12 deficiency and other consequences of autoimmune gastritis may coexist.','An elevated gastrin level does not itself prove gastrinoma.'], [['Type 1','Atrophic gastritis, reduced acid'],['Type 2','Gastrinoma-associated acid excess'],['Type 3','Sporadic, usually normal gastrin']], [EN], 'clinical_scenario')
q('A solitary 3-cm gastric NET occurs with normal gastrin and no atrophic gastritis. What is the best general interpretation?', 'A sporadic type 3 gastric NET requiring formal staging and specialist oncological assessment',[
 ('A typical tiny type 1 lesion suitable for automatic observation','Size and the absence of an atrophic hypergastrinemic background do not fit that assumption.'),('A benign lesion because serum gastrin is normal','Normal gastrin does not imply benign biology.'),('Proof of MEN1-related gastrinoma','The stated biochemical and mucosal context does not establish this.')],
 'Do not apply the indolent type 1 pathway to every gastric NET', '**Type 3 lesions can carry greater invasive and metastatic risk.**', ['Grade, depth and nodal/distant staging affect treatment.','Small selected low-grade superficial type 3 lesions are a different scenario from this 3-cm lesion.'], '**Choose treatment after staging rather than from the NET label alone.**', ['EUS and cross-sectional or receptor imaging may be relevant.','Expert pathology review can clarify differentiation and grade.'], [['Type 1 small lesion','Often lower-risk local pathway'],['Large sporadic lesion','Formal oncological assessment'],['Treatment selection','Size, grade, depth and stage']], [EN], 'clinical_scenario')
q('During symptomatic fasting hypoglycemia, glucose is low with inappropriately measurable insulin, elevated C-peptide and a negative sulfonylurea screen. Which mechanism is favored?', 'Endogenous hyperinsulinemia, with insulinoma among the key causes',[
 ('Exogenous insulin administration as the typical explanation','Exogenous insulin usually suppresses endogenous C-peptide.'),('Sulfonylurea exposure established despite the negative drug evaluation','The drug screen is used to investigate that alternative; assay coverage and timing still matter.'),('Non-insulin-mediated starvation hypoglycemia with appropriately suppressed insulin','The insulin is not appropriately suppressed in the stated setting.')],
 'Interpret insulin only at the time of verified hypoglycemia', '**A seemingly normal insulin concentration can be inappropriate when glucose is low.**', ['C-peptide and proinsulin help establish endogenous secretion.','A supervised evaluation and medication review precede localization.'], '**Biochemical confirmation comes before a search for a small tumor.**', ['Localize with appropriate pancreatic imaging and specialist techniques.','Other endogenous hyperinsulinemic disorders remain in the differential.'], [['Endogenous insulin','Insulin and C-peptide present'],['Exogenous insulin','C-peptide suppressed'],['Secretagogue exposure','Drug testing relevant']], [PN,NA], 'clinical_scenario')
q('A patient with a small insulinoma has recurrent hypoglycemia while awaiting definitive treatment. Which drug can suppress insulin release?', 'Diazoxide',[
 ('Metoclopramide','This is a prokinetic/antiemetic rather than a targeted insulin-suppression treatment.'),('Levothyroxine','Thyroid replacement does not directly address inappropriate tumor insulin secretion.'),('Mesalamine','This treats selected intestinal inflammatory disease, not insulinoma hypoglycemia.')],
 'Stabilize the hormone syndrome before definitive treatment', '**Diazoxide inhibits insulin secretion through beta-cell potassium-channel effects.**', ['Dietary support and glucose rescue remain necessary according to severity.','Fluid retention and other adverse effects require monitoring.'], '**Localize and assess the tumor for definitive management.**', ['Surgery can be curative for localized disease.','Somatostatin analogue effects on glucose can be complex and require specialist monitoring.'], [['Diazoxide','Suppresses insulin release'],['Glucose support','Immediate hypoglycemia correction'],['Localized tumor','Definitive surgical assessment']], [PN])
q('A patient has recurrent peptic ulcers, diarrhea, fasting hypergastrinemia and gastric pH of 1.5. What is the most relevant diagnostic interpretation?', 'Inappropriate hypergastrinemia in an acid-secretory state supports evaluation for gastrinoma',[
 ('Hypergastrinemia from autoimmune achlorhydria as the best fit','Achlorhydria would have a high rather than strongly acidic gastric pH.'),('A gastrin value alone proves gastrinoma in every PPI-treated patient','Acid suppression itself can raise gastrin and complicate interpretation.'),('The low pH excludes Zollinger–Ellison syndrome','Acid hypersecretion is a central feature of the syndrome.')],
 'The acid context separates appropriate from inappropriate gastrin elevation', '**Gastrin should normally fall in a strongly acidic stomach.**', ['PPIs and atrophic gastritis can cause secondary hypergastrinemia.','Specialist testing avoids unsafe unmonitored withdrawal of acid suppression.'], '**Treat acid hypersecretion while completing localization and staging.**', ['A PPI is central to controlling acid-mediated complications.','Assess for MEN1 when the phenotype or family history suggests it.'], [['High gastrin plus high pH','Secondary feedback response possible'],['High gastrin plus low pH','Inappropriate secretion concern'],['PPI exposure','Important testing confounder']], [PN,NA], 'clinical_scenario')
q('Profuse watery diarrhea continues during fasting and is associated with hypokalemia and reduced gastric acidity. Which functional pancreatic NET is classically associated with this pattern?', 'VIPoma',[
 ('Insulinoma','Its defining syndrome is endogenous hyperinsulinemic hypoglycemia.'),('Glucagonoma','Necrolytic migratory erythema, diabetes and weight loss are more characteristic.'),('Gastrinoma','It produces acid hypersecretion rather than the classic low-acid watery diarrhea syndrome.')],
 'A secretory stool phenotype can reveal a hormone syndrome', '**VIP promotes intestinal electrolyte and water secretion.**', ['Severe dehydration and potassium loss can be life-threatening.','Confirm the hormone abnormality in the right clinical setting and exclude other secretory causes.'], '**Correct fluid and electrolyte deficits before elective tumor treatment.**', ['Somatostatin analogues can help control secretion.','Localization, staging and resectability determine definitive treatment.'], [['VIPoma','Watery diarrhea and hypokalemia'],['Gastrinoma','Acid-peptic disease'],['Insulinoma','Hypoglycemia']], [PN], 'clinical_scenario')
q('Diabetes, weight loss and necrolytic migratory erythema occur with a pancreatic mass. Which tumor syndrome is most likely?', 'Glucagonoma',[
 ('Somatostatinoma','Diabetes, steatorrhea and gallstones are more characteristic than the stated rash.'),('Insulinoma','It produces hypoglycemia rather than the characteristic catabolic hyperglycemic syndrome.'),('VIPoma','Its hallmark is profound watery diarrhea with electrolyte loss.')],
 'Recognize the catabolic hormone phenotype', '**Excess glucagon can produce hyperglycemia, weight loss and a characteristic migratory dermatitis.**', ['Nutritional deficiencies and thromboembolic risk can complicate the syndrome.','The rash itself has a differential diagnosis and requires clinical correlation.'], '**Treat the metabolic and nutritional effects alongside the tumor.**', ['Somatostatin analogues can reduce secretory symptoms.','Assess stage and surgical suitability rather than treating the rash alone.'], [['Glucagonoma','Diabetes, catabolism, migratory rash'],['Somatostatinoma','Diabetes, steatorrhea, gallstones'],['VIPoma','Secretory diarrhea']], [PN,NA], 'clinical_scenario')
q('Which combination is most characteristic of somatostatinoma syndrome?', 'Diabetes, steatorrhea and gallstones',[
 ('Hypoglycemia, high insulin and high C-peptide','This suggests endogenous insulin excess.'),('Acid hypersecretion with refractory peptic ulceration','This suggests gastrinoma.'),('Isolated flushing with right-sided fibrotic valve disease','This suggests serotonin-mediated carcinoid syndrome.')],
 'An inhibitory hormone can disrupt several digestive functions', '**Somatostatin excess can inhibit insulin, pancreatic secretion and gallbladder contraction.**', ['The complete clinical syndrome is uncommon.','A tumor diagnosis requires integrated biochemical, imaging and pathological evidence.'], '**Manage the consequences as well as the lesion.**', ['Glycemic and nutritional care may be necessary.','Definitive treatment depends on site, grade and stage.'], [['Insulin inhibition','Diabetes'],['Digestive secretion inhibition','Steatorrhea'],['Gallbladder stasis','Gallstones']], [PN])
q('Hyperparathyroidism, a pituitary adenoma and a pancreatic or duodenal NET suggest which inherited syndrome?', 'Multiple endocrine neoplasia type 1',[
 ('MEN2','Medullary thyroid carcinoma and pheochromocytoma are central features of MEN2.'),('Familial adenomatous polyposis','This is an APC-related polyposis syndrome rather than the classic endocrine triad.'),('Lynch syndrome','This is a mismatch-repair cancer predisposition syndrome with a different phenotype.')],
 'A syndromic pattern changes evaluation of the patient and family', '**MEN1 classically involves parathyroid, pituitary and gastroenteropancreatic endocrine tumors.**', ['Multiple or small duodenal/pancreatic lesions can complicate localization and surgical planning.','Genetic counseling and syndrome-specific assessment are important.'], '**Do not treat each lesion as an unrelated sporadic event.**', ['Screen for other syndrome manifestations through a specialist pathway.','Family evaluation depends on the confirmed genetic diagnosis.'], [['MEN1','Parathyroid, pituitary, pancreatic/duodenal endocrine'],['MEN2','RET-associated medullary thyroid/pheochromocytoma pattern'],['Genetic confirmation','Guides family assessment']], [PN])
q('A patient taking a PPI has a modestly elevated chromogranin A but no established neuroendocrine tumor. What is the best interpretation?', 'Chromogranin A is nonspecific and medication, renal function and gastric disease can confound the result',[
 ('The result independently proves metastatic NET','It has inadequate specificity for that conclusion.'),('A normal value would exclude every NET','Sensitivity is incomplete and varies with tumor biology and burden.'),('The result identifies the exact hormone causing symptoms','Chromogranin A is not a syndrome-specific secreted hormone measurement.')],
 'A general neuroendocrine marker is not a stand-alone diagnosis', '**Chromogranin A must be interpreted within a convincing clinical and pathological context.**', ['PPI-associated hypergastrinemia and reduced renal clearance can raise it.','Do not stop essential acid suppression unsafely just to repeat a marker.'], '**Choose subsequent tests to answer the actual clinical question.**', ['Specific hormone testing follows the symptom syndrome.','Imaging and tissue establish and stage a suspected lesion.'], [['CgA elevation','Nonspecific contextual clue'],['Hormone-specific test','Evaluates a functional syndrome'],['Imaging and pathology','Establishes lesion and biology']], [GI,NA], 'clinical_scenario')

if __name__=='__main__':
    finalize('GI & pancreas',8,'Gastrointestinal Neuroendocrine Tumors','gi-net',rows,16)
